  "dimensions": [
    {
      "dimension":"scope",
      "explanation":"The SFC removes its specified prior-approval requirement for covered UCITS post-authorisation investment changes. Operator changes and notification alignment are separate measures. Management companies remain exposed to applicable post-vetting arrangements.",
